import{_ as a,o as e,c as i,a3 as o}from"./chunks/framework.CcKC9xfe.js";const m=JSON.parse('{"title":"Mail applications","description":"The mail applications tested against yarilo, with the versions, what was checked and what to know about each: Bulwark Mail and Twake Mail over JMAP, and any IMAP and Submission client.","frontmatter":{"description":"The mail applications tested against yarilo, with the versions, what was checked and what to know about each: Bulwark Mail and Twake Mail over JMAP, and any IMAP and Submission client.","head":[["link",{"rel":"canonical","href":"https://doc.yarilomail.org/latest/installation/clients.html"}],["meta",{"property":"og:url","content":"https://doc.yarilomail.org/latest/installation/clients.html"}],["meta",{"property":"og:title","content":"Mail applications"}],["meta",{"name":"twitter:title","content":"Mail applications"}],["meta",{"property":"og:description","content":"The mail applications tested against yarilo, with the versions, what was checked and what to know about each: Bulwark Mail and Twake Mail over JMAP, and any IMAP and Submission client."}],["meta",{"name":"twitter:description","content":"The mail applications tested against yarilo, with the versions, what was checked and what to know about each: Bulwark Mail and Twake Mail over JMAP, and any IMAP and Submission client."}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://doc.yarilomail.org/latest/installation/clients.html#article\\",\\"mainEntityOfPage\\":\\"https://doc.yarilomail.org/latest/installation/clients.html\\",\\"headline\\":\\"Mail applications\\",\\"description\\":\\"The mail applications tested against yarilo, with the versions, what was checked and what to know about each: Bulwark Mail and Twake Mail over JMAP, and any IMAP and Submission client.\\",\\"dateModified\\":\\"2026-10-26T09:08:48.000Z\\",\\"inLanguage\\":\\"en\\",\\"isPartOf\\":{\\"@id\\":\\"https://doc.yarilomail.org/#website\\"},\\"publisher\\":{\\"@id\\":\\"https://yarilomail.org/#organization\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Yarilo documentation\\",\\"item\\":\\"https://doc.yarilomail.org/latest/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Mail applications\\",\\"item\\":\\"https://doc.yarilomail.org/latest/installation/clients.html\\"}]}]}"]]},"headers":[],"relativePath":"installation/clients.md","filePath":"installation/clients.md","lastUpdated":1793005728000}'),l={name:"installation/clients.md"};function n(s,t,r,d,h,c){return e(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="mail-applications" tabindex="-1">Mail applications <a class="header-anchor" href="#mail-applications" aria-label="Permalink to &quot;Mail applications&quot;">​</a></h1><p>yarilo speaks standard protocols, so any client of them can be used. This page lists the applications tested against yarilo, what was checked with each, and what an operator or a user needs to know about them.</p><h2 id="web-applications-over-jmap" tabindex="-1">Web applications over JMAP <a class="header-anchor" href="#web-applications-over-jmap" aria-label="Permalink to &quot;Web applications over JMAP&quot;">​</a></h2><p>Both are separate web applications that the operator hosts and points at yarilo&#39;s JMAP endpoint. A browser calls yarilo from the application&#39;s own origin, so that origin must be listed in <a href="/latest/protocols/jmap.html#protocol.jmap.jmap_cors_allow_origins"><code>jmap_<wbr>cors_<wbr>allow_<wbr>origins</code></a>. Sending needs a Submission relay, as for any JMAP client (see <a href="/latest/protocols/jmap.html#sending-mail">Sending mail</a>).</p><table tabindex="0"><thead><tr><th style="text-align:left;">Application</th><th style="text-align:left;">Version tested</th><th style="text-align:left;">Status</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="https://github.com/bulwarkmail/webmail" target="_blank" rel="noreferrer nofollow">Bulwark Mail</a></td><td style="text-align:left;">1.17.1</td><td style="text-align:left;">works</td></tr><tr><td style="text-align:left;"><a href="https://github.com/linagora/tmail-flutter" target="_blank" rel="noreferrer nofollow">Twake Mail</a> (web)</td><td style="text-align:left;">0.40.2</td><td style="text-align:left;">works, with the notes below</td></tr></tbody></table><p>Tested on yarilo 2.4.5 in October 2026.</p><h3 id="bulwark-mail" tabindex="-1">Bulwark Mail <a class="header-anchor" href="#bulwark-mail" aria-label="Permalink to &quot;Bulwark Mail&quot;">​</a></h3><p>Checked: sign-in, the folder list, reading, flags, marking a folder read, creating a folder and moving mail into it, sending, the storage quota, and new mail appearing without a reload.</p><ul><li>New mail arrives over the JMAP EventSource stream; nothing extra is needed.</li><li>The storage quota is shown at the bottom of the side panel.</li></ul><h3 id="twake-mail" tabindex="-1">Twake Mail <a class="header-anchor" href="#twake-mail" aria-label="Permalink to &quot;Twake Mail&quot;">​</a></h3><p>Checked: sign-in, the folder list, reading, flags, folders, creating an identity, sending, the storage quota, and new mail appearing without a reload.</p><ul><li>Sending needs an identity created in the application. Twake Mail sends only from identities the user may delete, and the account&#39;s own address is not one of them. Create one once under <strong>Settings → Profiles → Identities → Create new identity</strong>, with the account&#39;s address; see <a href="/latest/protocols/jmap.html#identities">Identities</a>.</li><li>New mail without a reload needs the WebSocket ticket, on by default: Twake Mail opens the WebSocket only with one. With <a href="/latest/protocols/jmap.html#protocol.jmap.jmap_websocket_ticket_ttl"><code>jmap_<wbr>websocket_<wbr>ticket_<wbr>ttl: 0</code></a> the application works but shows new mail only after a reload. See <a href="/latest/protocols/jmap.html#tickets-for-browser-clients">Tickets for browser clients</a>.</li><li>The storage quota appears in the side panel only above 80% of the limit; it is always under <strong>Settings → Storage</strong>.</li><li>The mobile application was not tested.</li></ul><h2 id="contacts-and-calendars" tabindex="-1">Contacts and calendars <a class="header-anchor" href="#contacts-and-calendars" aria-label="Permalink to &quot;Contacts and calendars&quot;">​</a></h2><p>yarilo serves mail only. Neither application offers contacts or calendars against it, since yarilo does not advertise them.</p><h2 id="other-clients" tabindex="-1">Other clients <a class="header-anchor" href="#other-clients" aria-label="Permalink to &quot;Other clients&quot;">​</a></h2><p>Desktop and mobile mail applications connect over IMAP and Submission (and POP3 where it is enabled), with the hosts and ports the operator publishes. They are not listed here because none has been tested as a whole yet; how each finds its settings is on <a href="/latest/installation/autoconfig.html">Mail client autoconfiguration</a>.</p>',16)])])}const w=a(l,[["render",n]]);export{m as __pageData,w as default};
